<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Check, CirclePlus, Hammer, Wrench } from 'lucide-vue-next'
import { api } from '../api'
import { useSessionStore } from '../stores/session'
const session=useSessionStore()
const tickets=ref<any[]>([])
const properties=ref<any[]>([])
const vendors=ref<any[]>([])
const loading=ref(true)
const saving=ref(false)
const error=ref('')
const quoteInputs=ref<Record<string,string>>({})
const isManager=computed(()=>['ADMIN','OWNER','AGENT'].includes(session.session?.user.role||''))
const isVendor=computed(()=>session.session?.user.role==='VENDOR')
const canReport=computed(()=>['ADMIN','OWNER','AGENT','TENANT','BUYER'].includes(session.session?.user.role||''))
const customer=computed(()=>['BUYER','TENANT'].includes(session.session?.user.role||''))
const form=ref({propertyId:'',title:'',category:'Plumbing',priority:'MEDIUM',description:''})
const vendorForm=ref({name:'',service:'',phone:'',email:''})
async function load(){loading.value=true;try{const role=session.session?.user.role;const propertyRequest=['BUYER','TENANT'].includes(role||'')?api.get('/leases').then((r:any)=>({data:[...new Map(r.data.filter((x:any)=>x.status==='ACTIVE').map((x:any)=>[x.property.id,x.property])).values()]})):['ADMIN','OWNER','AGENT'].includes(role||'')?api.get('/portfolio/properties').then((r:any)=>({data:r.data.filter((property:any)=>property.status==='PUBLISHED')})):Promise.resolve({data:[]});const [t,p,v]=await Promise.all([api.get('/maintenance'),propertyRequest,isManager.value?api.get('/vendors'):Promise.resolve({data:[]})]);tickets.value=t.data;properties.value=p.data;vendors.value=v.data;if(!form.value.propertyId&&p.data.length)form.value.propertyId=p.data[0].id}catch(e:any){error.value=e.response?.data?.message||'Could not load maintenance desk.'}finally{loading.value=false}}
async function createTicket(){saving.value=true;error.value='';try{await api.post('/maintenance',form.value);form.value.title='';form.value.description='';await load()}catch(e:any){error.value=e.response?.data?.message||'Could not create maintenance request.'}finally{saving.value=false}}
async function addVendor(){saving.value=true;error.value='';try{await api.post('/vendors',vendorForm.value);vendorForm.value={name:'',service:'',phone:'',email:''};await load()}catch(e:any){error.value=e.response?.data?.message||'Could not add vendor.'}finally{saving.value=false}}
async function assign(ticket:any,event:Event){const vendorId=(event.target as HTMLSelectElement).value;if(!vendorId)return;try{await api.patch(`/maintenance/${ticket.id}/assign-vendor`,{vendorId,...(quoteInputs.value[ticket.id]?{quotedCost:Number(quoteInputs.value[ticket.id])}:{})});await load()}catch(e:any){error.value=e.response?.data?.message||'Could not assign vendor.'}}
async function changeStatus(ticket:any,status:string){try{await api.patch(`/maintenance/${ticket.id}/status`,{status});await load()}catch(e:any){error.value=e.response?.data?.message||'Could not update maintenance request.'}}
const date=(d:string)=>new Date(d).toLocaleDateString([], {dateStyle:'medium'})
onMounted(load)
</script>

<template><section class="workspace-content"><div class="section-toolbar"><div><h2>Maintenance desk</h2><p>Report a repair, route it to a vendor, and follow its progress.</p></div><span class="count-pill">{{tickets.filter(x=>!['COMPLETED','CLOSED'].includes(x.status)).length}} open</span></div><div v-if="error" class="notice error-notice">{{error}}</div><div class="maintenance-layout"><form v-if="canReport&&(!customer||properties.length)" class="panel-card compact-form" @submit.prevent="createTicket"><div class="eyebrow muted-eyebrow">NEW REQUEST</div><h3>What needs attention?</h3><label>Property<select v-model="form.propertyId" required><option v-for="p in properties" :key="p.id" :value="p.id">{{p.title}} · {{p.city}}</option></select></label><label>Issue title<input v-model="form.title" required placeholder="e.g. Kitchen tap is leaking"/></label><label>Category<select v-model="form.category"><option>Plumbing</option><option>Electrical</option><option>HVAC</option><option>Appliance</option><option>Carpentry</option><option>Cleaning</option><option>Security</option><option>Painting</option><option>General</option></select></label><label>Priority<select v-model="form.priority"><option value="LOW">Low</option><option value="MEDIUM">Normal</option><option value="HIGH">High</option><option value="URGENT">Urgent</option></select></label><label>Details<textarea v-model="form.description" required rows="4" placeholder="Describe the problem and when we can access the property…"></textarea></label><button class="button button-primary full-button" :disabled="saving||!properties.length"><CirclePlus :size="15"/> Submit request</button></form><div class="ticket-list"><div v-if="customer&&!properties.length&&!loading" class="small-empty">Maintenance requests are available once you have an active lease.</div><div v-if="loading" class="loading-row">Loading maintenance tickets…</div><div v-else-if="!tickets.length" class="empty-state compact-empty"><span class="empty-icon"><Wrench/></span><h3>No requests yet</h3><p>Submitted repairs will be tracked here.</p></div><article v-for="ticket in tickets" :key="ticket.id" class="ticket-card"><div class="ticket-topline"><span class="ticket-id">{{ticket.id.slice(-7).toUpperCase()}}</span><span class="status-pill" :class="ticket.priority.toLowerCase()">{{ticket.priority}}</span><span class="status-pill" :class="ticket.status.toLowerCase()">{{ticket.status.replace('_',' ')}}</span></div><h3>{{ticket.title}}</h3><p class="ticket-location">{{ticket.property.title}} · {{ticket.property.community}}, {{ticket.property.city}}</p><p class="ticket-description">{{ticket.description}}</p><div class="ticket-meta"><span><Hammer :size="14"/>{{ticket.category}}</span><span>{{date(ticket.createdAt)}}</span><span v-if="ticket.slaDueAt">SLA by {{date(ticket.slaDueAt)}}</span><span v-if="ticket.requester">Reported by {{ticket.requester.name}}</span></div><div v-if="ticket.vendor" class="vendor-assigned"><Check :size="14"/> Assigned to <b>{{ticket.vendor.name}}</b> · {{ticket.vendor.service}}<span v-if="ticket.quotedCost">· PKR {{Number(ticket.quotedCost).toLocaleString()}}</span></div><div v-if="isManager" class="ticket-actions"><select :value="ticket.vendorId||''" aria-label="Assign vendor" @change="assign(ticket,$event)"><option value="">{{ticket.vendor?'Change vendor':'Assign vendor'}}</option><option v-for="v in vendors" :key="v.id" :value="v.id">{{v.name}} · {{v.service}}</option></select><input v-model="quoteInputs[ticket.id]" type="number" min="0" placeholder="Quote (PKR)" aria-label="Vendor quoted cost"/><select :value="ticket.status" aria-label="Update maintenance status" @change="changeStatus(ticket,($event.target as HTMLSelectElement).value)"><option value="REQUESTED">Requested</option><option value="REVIEWED">Reviewed</option><option value="ASSIGNED">Assigned</option><option value="SCHEDULED">Scheduled</option><option value="IN_PROGRESS">In progress</option><option value="COMPLETED">Completed</option><option value="CLOSED">Closed</option></select></div><div v-else-if="isVendor" class="ticket-actions vendor-job-actions"><span>Update assigned job</span><select :value="ticket.status" aria-label="Update assigned job" @change="changeStatus(ticket,($event.target as HTMLSelectElement).value)"><option v-if="ticket.status==='ASSIGNED'" value="SCHEDULED">Schedule visit</option><option v-if="ticket.status==='SCHEDULED'" value="IN_PROGRESS">Start work</option><option v-if="ticket.status==='IN_PROGRESS'" value="COMPLETED">Complete job</option></select></div></article></div></div><section v-if="isManager" class="vendor-panel"><div class="section-toolbar"><div><h2>Service providers</h2><p>Assign organization vendors to open maintenance requests.</p></div><span class="count-pill">{{vendors.length}} active</span></div><div class="vendor-panel-body"><div class="vendor-list"><article v-for="vendor in vendors" :key="vendor.id"><span class="vendor-icon"><Hammer/></span><span><b>{{vendor.name}}</b><small>{{vendor.service}}<template v-if="vendor.phone"> · {{vendor.phone}}</template></small></span><span class="vendor-active">Active</span></article><div v-if="!vendors.length" class="small-empty">Add a vendor so your team can assign incoming maintenance work.</div></div><form class="vendor-form" @submit.prevent="addVendor"><h3>Add service provider</h3><label>Name<input v-model="vendorForm.name" required placeholder="Northside Plumbing"/></label><label>Service<input v-model="vendorForm.service" required placeholder="Plumbing & drainage"/></label><div class="vendor-form-row"><label>Phone<input v-model="vendorForm.phone" placeholder="+92…"/></label><label>Email<input v-model="vendorForm.email" type="email" placeholder="team@example.com"/></label></div><button class="button button-outline full-button" :disabled="saving">Add vendor</button></form></div></section></section></template>
